    }
  }

  const cfg = limiares.acoes;
  const set = new Set(situacao === 'ALERTA' ? cfg.alerta : []);
  for (const p of problemas) for (const a of (p.area && cfg.por_area[p.area]) || []) set.add(a);
  if (requer_humano) set.delete('TRELLO');
  const acoes = cfg.ordem.filter(a => set.has(a));

  return {
    status_guardrail: g.status, status_llm, status_final, sensor_fault: g.sensor_fault, requer_humano,
    situacao, problemas, recomendacao_padrao: recomendacaoPadrao(situacao, status_final, problemas, limiares),
    acoes_previstas: acoes,
  };
}

/** Recomendação determinística (usada quando o LLM não responde): uma frase por área com problema. */
function recomendacaoPadrao(situacao, statusFinal, problemas, limiares) {
  const r = limiares.recomendacoes;
  if (situacao === 'NORMAL') return statusFinal === 'ATENCAO' ? r.atencao : r.normal;
  const partes = [];
  if (problemas.some(p => !p.area && p.descricao.startsWith(limiares.problemas.dados))) partes.push(r.dados);
  for (const area of ['manutencao', 'energia', 'producao']) if (problemas.some(p => p.area === area)) partes.push(r[area]);
  return (partes.length ? partes : [r.geral]).join(' ');
}

/** Texto no formato do enunciado: Máquina / Situação / Problemas identificados / RECOMENDAÇÃO. */
function relatorioTexto(d) {
  const linhas = [`Máquina: ${d.id_maquina}`, `Situação: ${d.situacao}`];
  if (d.problemas && d.problemas.length) {
    linhas.push('Problemas identificados:');
    for (const p of d.problemas) {
      const num = p.valor !== null && p.valor !== undefined ? ` (${p.valor}; limite ${p.limite})` : '';
      linhas.push(`- ${p.descricao}${num}`);
    }
  }
  linhas.push(`RECOMENDAÇÃO: ${d.recomendacao}`);
  return linhas.join('\n');
}

function round2(n) { return Math.round(n * 100) / 100; }

// --- Fiação (WF-10, nó "Consolidar") ----------------------------------------
// consolidar() acima é o mesmo contracts/guardrail.js::consolidar (piso de
// severidade = max(status_llm, status_guardrail); nunca é rebaixado pelo LLM).
const stub = $input.first().json;
const limiares = $('Preparar Payload').first().json.limiares;
// especialistasRequeremHumano: algum parecer com dados_insuficientes: true (o piso do guardrail continua mandando).
const pareceresLista = Object.values(stub.pareceres || {});
const especialistasRequeremHumano = pareceresLista.some((p) => p && p.dados_insuficientes === true);
const base = consolidar(stub.leitura, stub.status_llm, limiares, especialistasRequeremHumano, stub.pareceres);

const decisao = {
  id_decisao: null,
  id_leitura: stub.leitura.id_leitura,
  id_maquina: stub.leitura.id_maquina,
  ts: stub.leitura.ts,
  status_guardrail: base.status_guardrail,
  status_llm: base.status_llm,
  status_final: base.status_final,
  sensor_fault: base.sensor_fault,
  requer_humano: base.requer_humano,
  especialistas: stub.pareceres,
  resumo_operador: stub.resumo_operador,
  justificativa: stub.justificativa,
  situacao: base.situacao,
  problemas: base.problemas,
  // recomendação do LLM quando ele respondeu; senão a padrão por área (limiares.recomendacoes)
  recomendacao: (stub.status_llm && stub.recomendacao) ? stub.recomendacao : base.recomendacao_padrao,
  acoes_previstas: base.acoes_previstas,
  modelo: stub.modelo ?? null,
  latencia_ms: Date.now() - stub.inicio_ms,
};

// Texto no formato do enunciado (Máquina / Situação / Problemas / RECOMENDAÇÃO), usado no Telegram.
decisao.relatorio = relatorioTexto(decisao);

return [{ json: { decisao } }];

// Achata o objeto "decisao" (contracts/decisao.schema.json) nas colunas da
// tabela decisoes (db/01_schema.sql). Colunas JSON (pareceres, acoes_previstas)
// vão serializadas; o resto é 1:1.
const decisao = $input.first().json.decisao;
return [{
  json: {
    id_leitura: decisao.id_leitura,
    id_maquina: decisao.id_maquina,
    status_guardrail: decisao.status_guardrail,
    status_llm: decisao.status_llm,
    status_final: decisao.status_final,
    sensor_fault: decisao.sensor_fault,
    requer_humano: decisao.requer_humano,
    resumo_operador: decisao.resumo_operador,
    justificativa: decisao.justificativa,
    situacao: decisao.situacao,
    problemas: JSON.stringify(decisao.problemas),
    recomendacao: decisao.recomendacao,
    pareceres: JSON.stringify(decisao.especialistas),
    acoes_previstas: JSON.stringify(decisao.acoes_previstas),
    modelo: decisao.modelo,
    latencia_ms: decisao.latencia_ms,
  },
}];

// Junta o id_decisao (auto-incremento do INSERT) de volta no objeto decisao
// original (contracts/decisao.schema.json), e já monta o payload de entrada
// do WF-30 ({decisao, id_decisao}).
const decisaoBase = $('Consolidar').first().json.decisao;
const insertResult = $input.first().json;
const insertId = (insertResult.data && insertResult.data.insertId !== undefined)
  ? insertResult.data.insertId
  : insertResult.insertId;
const decisao = Object.assign({}, decisaoBase, { id_decisao: insertId });
return [{ json: { decisao, id_decisao: decisao.id_decisao } }];

// Saída do WF-10: a decisão completa, com id_decisao. Não depende do que o
// WF-30 (ainda em construção em paralelo por outro subagente) devolveu --
// só usamos a decisão já montada no nó "Montar Decisao Final".
const decisao = $('Montar Decisao Final').first().json.decisao;
return [{ json: decisao }];

// Prepara a chamada do supervisor (T12).
// Decide SE o LLM é acionado:
//   - atalho: id_maquina inválido ou máquina desconhecida => não há o que diagnosticar; exige humano;
//   - flag de teste: entrada.usar_llm === false (WF-01 com ?llm=0) => caminho determinístico.
// O WF-00 (MQTT) não manda usar_llm => padrão true (sempre usa o LLM).
const anterior = $('Validar e Guardrail').first().json;
const insertResult = $('Inserir Leitura').first().json;
const insertId = (insertResult.data && insertResult.data.insertId !== undefined)
  ? insertResult.data.insertId
  : insertResult.insertId;
const leitura = Object.assign({}, anterior.leitura, { id_leitura: insertId });

const entrada = $('Trigger').first().json;
const uf = entrada.usar_llm;
const flagLlm = !(uf === false || uf === 'false' || uf === 0 || uf === '0');
const val = leitura.validacao;
const atalho = val.id_invalido === true || val.maquina_conhecida === false;
const motivo_sem_llm = atalho ? 'atalho' : (!flagLlm ? 'flag' : null);

const prompt_usuario =
  'LEITURA (JSON):\n' + JSON.stringify(leitura) +
  '\n\nConsulte as três ferramentas (uma vez cada), consolide os pareceres e responda.' +
  '\n\nENTREGA: ao terminar, chame a ferramenta format_final_json_response com o argumento ' +
  '{"output": {"status": ..., "resumo_operador": ..., "justificativa": ..., "recomendacao": ...}} (a decisão vai DENTRO da chave "output").';

return [{ json: {
  leitura,
  inicio_ms: anterior.inicio_ms,
  chamar_llm: motivo_sem_llm === null,
  motivo_sem_llm,
  prompt_usuario,
} }];

// Classifica o erro do agente supervisor. Rate limit (429 / "too many requests" / "rate limit" / TPM)
// com menos de 3 tentativas => espera ativa e volta ao supervisor (o "try again in Xs" da mensagem,
// entre 10 e 60 s; sem sugestão, 30 s). Outro erro, ou a 3ª tentativa => falha_llm (fallback determinístico).
// $runIndex = nº de vezes que ESTE nó já rodou nesta execução = falhas anteriores do agente.
const MAX_TENTATIVAS = 3;
const bruto = $input.first().json;
const err = bruto && bruto.error !== undefined ? bruto.error : bruto;
let msg = err;
if (msg && typeof msg === 'object') msg = msg.message || msg.description || JSON.stringify(msg);
msg = String(msg === undefined || msg === null ? 'erro desconhecido' : msg);

let detalhe = '';
try {
  if (err && typeof err === 'object') {
    detalhe = [err.message, err.description, err.cause && err.cause.message, JSON.stringify(err).slice(0, 3000)].filter(Boolean).join(' | ');
  }
} catch (x) { /* ignora */ }
const texto = msg + ' | ' + detalhe;

const ehRateLimit = /\b(429|500|502|503|504)\b|too many requests|tool call validation|rate.?limit|tokens per minute|requests per minute|service unavailable|overloaded|bad gateway|timed? ?out|ECONNRESET/i.test(texto);
const tentativa = $runIndex + 1;

let espera_s = 30;
const m = texto.match(/try again in\s+(?:(\d+)m)?\s*([\d.]+)\s*s\b/i);
if (m) espera_s = Math.min(60, Math.max(10, Math.ceil(Number(m[1] || 0) * 60 + Number(m[2])) + 1));

// Carrega o contexto (prompt_usuario etc.): o Wait devolve ESTE item ao agente.
const ctx = $('Preparar Supervisor').first().json;
return [{ json: {
  ...ctx,
  retentar: ehRateLimit && tentativa < MAX_TENTATIVAS,
  falha_llm: true,
  rate_limit: ehRateLimit,
  tentativa,
  espera_s,
  erro_msg: msg.slice(0, 500),
} }];

// Resultado do supervisor (T12). Três entradas possíveis (só uma dispara por execução):
//   1) sem LLM  : item de "Chamar LLM?" (ramo false): chamar_llm === false (atalho ou flag usar_llm=false);
//   2) falha    : item de "Classificar Erro Supervisor" (ramo sem retentativa): falha_llm === true;
//   3) agente   : saída do AI Agent { output, intermediateSteps }.
// Em 1 e 2, ou se a saída do agente for inválida/vazia, usa gerarFallbackOperador() (determinístico)
// e status_llm = null. Os pareceres dos especialistas são extraídos de intermediateSteps POR CÓDIGO
// (o LLM não os reescreve), pelo nome da tool; null para a tool não chamada ou que falhou.

function gerarFallbackOperador(leitura, limiares, motivo) {
  const rotulos = limiares.status.rotulos;
  const val = leitura.validacao;
  const g = leitura.guardrail;

  if (!val.ok) {
    const motivos = [];
    if (val.id_invalido) motivos.push('id_maquina inválido ou fora do padrão');
    if (!val.maquina_conhecida) motivos.push('máquina desconhecida (' + leitura.id_maquina + ')');
    if (val.campos_ausentes.length) motivos.push('campo(s) ausente(s): ' + val.campos_ausentes.join(', '));
    if (val.tipo_invalido.length) motivos.push('tipo inválido em: ' + val.tipo_invalido.join(', '));
    if (val.fora_faixa_fisica.length) motivos.push('fora da faixa física: ' + val.fora_faixa_fisica.join(', '));
    const motivoPrincipal = motivos[0] || 'validação falhou';
    const resumo_operador = ('Dados inconsistentes: ' + motivoPrincipal + '. Verificação humana necessária.').slice(0, 500);
    const justificativa = (
      'Verificação humana necessária. Motivo(s): ' + motivos.join('; ') + '. ' +
      'Guardrail determinístico (config/limiares.json): ' + rotulos[g.status] + '. ' + motivo
    ).slice(0, 2000);
    return { resumo_operador, justificativa };
  }

  if (!g.violacoes.length) {
    return {
      resumo_operador: (leitura.id_maquina + ' em ' + rotulos[g.status] + ': nenhuma grandeza fora do limiar.').slice(0, 500),
      justificativa: (
        'Guardrail determinístico avaliou todas as grandezas dentro dos limiares configurados ' +
        '(config/limiares.json). Status: ' + rotulos[g.status] + '. ' + motivo
      ).slice(0, 2000),
    };
  }

  const partes = g.violacoes.map((v) => v.grandeza + ' ' + v.valor + ' (limite ' + v.limite + ', ' + rotulos[v.status] + ')');
  const resumo_operador = (leitura.id_maquina + ' em ' + rotulos[g.status] + ': ' + partes.join('; ') + '.').slice(0, 500);
  const justificativa = (
    'Guardrail determinístico (config/limiares.json) classificou ' + leitura.id_maquina + ' como ' + rotulos[g.status] + '. ' +
    'Violações: ' + partes.join('; ') + '. ' +
    'Especialistas: manutenção=' + rotulos[g.por_especialista.manutencao] +
    ', produção=' + rotulos[g.por_especialista.producao] +
    ', energia=' + rotulos[g.por_especialista.energia] + '. ' + motivo
  ).slice(0, 2000);
  return { resumo_operador, justificativa };
}

const ORDEM = ['NORMAL', 'ATENCAO', 'CRITICO'];
const TOOL_PARA_AREA = { especialista_manutencao: 'manutencao', especialista_producao: 'producao', especialista_energia: 'energia' };
const ctx = $('Preparar Supervisor').first().json;
const limiares = $('Preparar Payload').first().json.limiares;
const leitura = ctx.leitura;
const j = $input.first().json;
const MODELO = $env.GROQ_MODEL_SUPERVISOR || null;

function tentaJson(v) {
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (x) { return v; }
}

// Extrai o parecer de cada tool de intermediateSteps.
const pareceres = { manutencao: null, producao: null, energia: null };
const tools_chamadas = [];
const passos = Array.isArray(j.intermediateSteps) ? j.intermediateSteps : [];
for (const p of passos) {
  const a = (p && p.action) || {};
  const area = TOOL_PARA_AREA[a.tool || a.name];
  if (!area) continue;
  tools_chamadas.push(a.tool || a.name);
  let obs = tentaJson(p.observation);
  // observation = string JSON de uma LISTA de itens ([{...}]); desembrulha.
  if (Array.isArray(obs) && obs.length === 1) obs = obs[0];
  if (obs && typeof obs === 'object' && !Array.isArray(obs) && obs.json && typeof obs.json === 'object' && Object.keys(obs).length === 1) obs = obs.json;
  if (obs && typeof obs === 'object' && !Array.isArray(obs) && obs.response !== undefined && Object.keys(obs).length === 1) obs = tentaJson(obs.response);
  const parecer = obs && typeof obs === 'object' ? obs.parecer : null;
  if (parecer && typeof parecer === 'object' && !Array.isArray(parecer) && ORDEM.includes(parecer.status)) pareceres[area] = parecer;
}

let modo;
let motivo;
let status_llm = null;
let resumo_operador;
let justificativa;
let recomendacao = null;
let modelo = null;
let erro = null;

if (j.chamar_llm === false) {
  modo = 'sem_llm';
  motivo = ctx.motivo_sem_llm === 'atalho'
    ? 'Supervisor LLM não acionado: id_maquina inválido ou máquina desconhecida, sem o que diagnosticar (atalho sem LLM); decisão exige verificação humana.'
    : 'Supervisor LLM não acionado (usar_llm=false, modo de teste determinístico do guardrail).';
} else if (j.falha_llm === true) {
  modo = 'falha';
  erro = String(j.erro_msg || 'erro desconhecido').slice(0, 200);
  motivo = 'Supervisor LLM indisponível após ' + j.tentativa + ' tentativa(s) (' + erro + '); decisão apoiada no guardrail e nos pareceres disponíveis.';
} else {
  let out = tentaJson(j.output);
  if (typeof out === 'string') out = tentaJson(out);
  const valido = out && typeof out === 'object' && !Array.isArray(out)
    && ORDEM.includes(out.status)
    && typeof out.resumo_operador === 'string' && out.resumo_operador.trim().length > 0
    && typeof out.justificativa === 'string' && out.justificativa.trim().length > 0;
  if (valido && typeof out.recomendacao === 'string' && out.recomendacao.trim()) recomendacao = out.recomendacao.trim().slice(0, 500);
  if (valido) {
    modo = 'llm';
    status_llm = out.status;
    resumo_operador = out.resumo_operador.trim().slice(0, 500);
    justificativa = out.justificativa.trim().slice(0, 2000);
    modelo = MODELO;
  } else {
    modo = 'falha';
    erro = 'saída do supervisor vazia ou fora do formato';
    motivo = 'Supervisor LLM devolveu ' + erro + '; decisão apoiada no guardrail e nos pareceres disponíveis.';
  }
}

if (modo !== 'llm') {
  const fb = gerarFallbackOperador(leitura, limiares, motivo);
  resumo_operador = fb.resumo_operador;
  justificativa = fb.justificativa;
}

return [{
  json: {
    leitura,
    status_llm,
    pareceres,
    resumo_operador,
    justificativa,
    recomendacao,
    modelo,
    inicio_ms: ctx.inicio_ms,
    supervisor: { modo, erro, tools_chamadas },
  },
}];
